"use client";
import { FormEventHandler, useState } from "react";
import { motion } from "framer-motion";
import { redirect, useRouter } from "next/navigation";
import { ClipLoader } from "react-spinners";
import { AiOutlineUser, AiOutlineShop, AiOutlineTool } from "react-icons/ai";
import axios from "axios";

export default function EditRolePhone() {
  const [role, setRole] = useState<string>("");
  const [phone, setPhone] = useState<string>("");
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  const roles = [
    { label: "Admin", value: "admin", icon: <AiOutlineTool size={35} /> },
    { label: "Vendor", value: "vendor", icon: <AiOutlineShop size={35} /> },
    { label: "User", value: "user", icon: <AiOutlineUser size={35} /> },
  ];

  const handleSubmit  = async  (e: React.FormEvent) => {
    e.preventDefault();
    if (!role || !phone) {
      alert("Please select a role and enter your phone number.");
      return;
    }
    setLoading(true);
    try {
      const result = await axios.post("/api/user/edit-role-mobile" , {role , phone})
      setLoading(false);
      router.push("/")
     
      
      
    } catch (error) {
      console.log(error)
      setLoading(false);
    }

   
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-gray-900 via-black to-gray-900 text-white p-6">
      <motion.div
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="w-full max-w-md bg-white/10 backdrop-blur-md rounded-3xl shadow-xl p-8 border border-white/10"
      >
        <h2 className="text-3xl font-semibold text-center mb-4">Choose Your Role</h2>
        <p className="text-center text-gray-300 mb-6 text-sm">
          Select your role and enter your mobile number to continue.
        </p>

        <form onSubmit={handleSubmit} className="flex flex-col gap-6">

          {/* 📞 Mobile Number Input */}
          <input
            type="text"
            placeholder="Enter Mobile Number"
            maxLength={10}
            pattern="[0-9]{10}"
            required
            className="bg-white/10 border border-white/30 rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
          />

          {/* 🔘 Role Selection Cards */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            {roles.map((rol) => (
              <motion.div
                key={rol.value}
                whileHover={{ scale: 1.05 }}
                onClick={() => setRole(rol.value)}
                className={`cursor-pointer p-4 text-center rounded-xl border backdrop-blur-md transition ${
                  role === rol.value
                    ? "border-blue-500 bg-blue-500/40"
                    : "border-white/20 bg-white/10 hover:bg-white/20"
                }`}
              >
                <div className="flex justify-center mb-2">{rol.icon}</div>
                <p className="font-medium">{rol.label}</p>
              </motion.div>
            ))}
          </div>

          {/* Submit Button */}
          <button
            type="submit"
            disabled={loading}
            className="bg-gradient-to-r from-blue-500 to-blue-700 py-3 rounded-xl font-medium hover:opacity-90 transition disabled:opacity-50"
          >
            {loading ? <ClipLoader size={26} color="white" /> : "Continue"}
          </button>
        </form>
      </motion.div>
    </div>
  );
}
